    public function run()
    {
        $params = ['name' => 'H5P.SortParagraphs', 'major_version' => 0, 'minor_version' => 11];
        if (DB::table('h5p_libraries')->where($params)->exists()) {
            return;
        }

        $libId = DB::table('h5p_libraries')->insertGetId([
            'name'             => 'H5P.SortParagraphs',
            'title'            => 'Sort the Paragraphs',
            'major_version'    => 0,
            'minor_version'    => 11,
            'patch_version'    => 16,
            'runnable'         => 1,
            'restricted'       => 0,
            'fullscreen'       => 0,
            'embed_types'      => 'iframe',
            'preloaded_js'     => 'dist/h5p-sort-paragraphs.js',
            'preloaded_css'    => 'dist/h5p-sort-paragraphs.css',
            'drop_library_css' => '',
            'semantics'        => $this->getSemantics(),
            'tutorial_url'     => '',
            'has_icon'         => 1,
            'created_at'       => now(),
            'updated_at'       => now(),
        ]);

        $this->insertDependentLibraries($libId);
        $this->insertLanguages($libId);
    }

    private function insertDependentLibraries(int $libId): void
    {
        $preloaded = [
            ['name' => 'FontAwesome',  'major_version' => 4, 'minor_version' => 5],
            ['name' => 'H5P.Question', 'major_version' => 1, 'minor_version' => 5],
            ['name' => 'H5P.JoubelUI', 'major_version' => 1, 'minor_version' => 3],
        ];
        foreach ($preloaded as $dep) {
            $lib = DB::table('h5p_libraries')->where($dep)->first();
            if ($lib) {
                DB::table('h5p_libraries_libraries')->insert([
                    'library_id'          => $libId,
                    'required_library_id' => $lib->id,
                    'dependency_type'     => 'preloaded',
                ]);
            }
        }

        $editor = [
            ['name' => 'H5PEditor.RangeList', 'major_version' => 1, 'minor_version' => 0],
            ['name' => 'H5PEditor.ShowWhen',  'major_version' => 1, 'minor_version' => 0],
        ];
        foreach ($editor as $dep) {
            $lib = DB::table('h5p_libraries')->where($dep)->first();
            if ($lib) {
                DB::table('h5p_libraries_libraries')->insert([
                    'library_id'          => $libId,
                    'required_library_id' => $lib->id,
                    'dependency_type'     => 'editor',
                ]);
            }
        }
    }

