"},{"label":"Instrucció quan se selecciona un paràgraf","default":"Prem la barra espaiadora per reordenar"},{"label":"Instrucció quan s\'agafa un paràgraf","default":"Prem les tecles de fletxa amunt i avall per canviar-ne la posició, la barra espaiadora per deixar-lo anar i la tecla d\'escapada per cancel·lar"},{"label":"Agafat","default":"Agafat"},{"label":"Mogut","default":"Mogut"},{"label":"Deixat","default":"Deixat"},{"label":"S’ha cancel·lat la reordenació","default":"S’ha cancel·lat la reordenació"},{"description":"Va seguit de \"Numeració de paràgrafs\".","label":"Posició final","default":"Posició final"},{"description":"Va seguit de \"correcte\" o \"incorrecte\".","label":"Paràgraf següent","default":"Paràgraf següent"},{"description":"Va seguit de \"Numeració de paràgrafs\".","label":"Paràgraf correcte","default":"Paràgraf a la posició correcta"}]}]}']);
        DB::table('h5p_libraries_languages')->insert(['library_id' => $libId, 'language_code' => 'cs', 'translation' => '{"semantics":[{"label":"Média","fields":[{"label":"Typ","description":"Volitelná média zobrazená nad otázkou."},{"label":"Zakázat zvětšení obrazu"}]},{"label":"Popis úlohy","placeholder":"Popište, co by vaši studenti měli dělat...","description":"Co by vaši studenti měli vědět."},{"label":"Odstavce","entity":"odstavec","field":{"label":"Odstavec"}},{"label":"Celková zpětná vazba","fields":[{"widgets":[{"label":"Výchozí"}],"label":"Definujte vlastní zpětnou vazbu pro jakýkoli rozsah skóre","description":"Klepnutím na tlačítko \"Přidat rozsah\" přidáte libovolný počet rozsahů. Příklad: 0-20% špatné skóre, 21-91% průměrné skóre, 91-100% výborné skóre!","entity":"rozsah","field":{"fields":[{"label":"Rozsah skóre"},{},{"label":"Zpětná vazba pro definovaný rozsah skóre","placeholder":"Vyplňte zpětnou vazbu"}]}}]},{"label":"Nastavení chování","description":"Tyto možnosti vám umožní řídit, jak se bude úloha chovat.","fields":[{"label":"Bodovací režim","description":"Rozhodněte se, zda udělit body za každý správně umístěný odstavec nebo za každý odstavec, který je umístěn za odstavcem, za kterým má být umístěn („správné pořadí“)","options":[{"label":"Správně umístěný odstavec"},{"label":"Správná sekvence"}]},{"label":"Použití sankcí","description":"Rozhodněte se, zda chcete redukovat bod za každý odstavec, který není správně umístěn."},{"label":"Duplicitní odstavce jsou zaměnitelné","description":"Je-li nastaveno, při kontrole odpovědi budou duplicitní odstavce považovány za identické, pokud je jejich prostý text stejný."},{"label":"Přidat tlačítka pro pohyb","description":"Na mobilních zařízeních mohou tlačítka pro přesouvání odstavců nabídnout další výhodu usnadnění. Pokud chcete, můžete je deaktivovat zde."},{"label":"Povolit tlačítko \"Opakovat\""},{"label":"Povolit tlačítko \"Zobrazit řešení\""}]},{"label":"Uživatelské rozhraní","fields":[{"label":"Popis tlačítka \"Zkontrolovat\"","default":"Zkontrolovat"},{"label":"Text pro tlačítko \"Odevzdat\"","default":"Odeslat"},{"label":"Text pro tlačítko \"Opakovat\"","default":"Opakovat"},{"label":"Text tlačítka \"Zobrazit řešení\"","default":"Zobrazit řešení"},{"label":"Název tlačítka „Nahoru“","default":"Nahoru"},{"label":"Název tlačítka \"Dolů\"","default":"Dolů"},{"label":"Název tlačítka, že je zakázáno","default":"Zakázáno"}]},{"label":"Čtecí zařízení","fields":[{"label":"Popisek podpůrné technologie pro tlačítko \"Zkontrolovat\"","default":"Zkontrolovat odpovědi. Odpovědi budou označeny jako správné nebo nesprávné."},{"label":"Popisek podpůrné technologie pro tlačítko „Zobrazit řešení“","default":"Zobrazit řešení. Zobrazí se správné řešení."},{"label":"Popisek podpůrné technologie pro tlačítko „Opakovat“","default":"Zopakovat úkol. Resetovat všechny prvky a spustit úlohu znovu."},{"label":"Váš výsledek","description":"@score bude nahrazeno počtem bodů. @total bude nahrazeno maximálním možným počtem bodů.","default":"Získal jste @score z @total bodů"},{"label":"Popis seznamu","default":"Tříditelný seznam odstavců."},{"label":"Popis seznamu (kontrola odpovědi)","default":"Seznam odstavců s výsledky."},{"label":"Popis seznamu (ukázat řešení)","default":"Seznam odstavců s řešeními."},{"label":"Odstavec","default":"Odstavec"},{"label":"Správně","default":"správně"},{"label":"Špatně","default":"špatně"},{"description":"@score bude nahrazeno 1 nebo -1.","label":"Vysvětlení skóre","default":"@score bodů"},{"description":"@current bude nahrazeno aktuálním číslem odstavce. @total bude nahrazeno počtem odstavců.","label":"Číslování odstavců","default":"@current z @total"},{"description":"Bude následovat \"Číslování odstavců\".","label":"Aktuální pozice v seznamu","default":"Aktuální pozice v seznamu"},{"label":"Pokyn při výběru odstavce","default":"Stisknutím mezerníku změníte pořadí"},{"label":"Pokyn při zachycení odstavce","default":"Stisknutím kláves se šipkami nahoru a dolů změníte polohu, mezerníkem jej upustíte, stisknutím klávesy Escape zrušíte"},{"label":"Zachyceno","default":"Zachyceno"},{"label":"Přesunuto","default":"Přesunuto"},{"label":"Umístěno","default":"Umístěno"},{"label":"Změna řazení zrušena","default":"Změna řazení zrušena"},{"description":"Bude následovat \"Číslování odstavců\".","label":"Konečná pozice","default":"Konečná pozice"},{"description":"Bude následovat „správně“ nebo „špatně“.","label":"Další odstavec","default":"Další odstavec"},{"description":"Bude následovat \"Číslování odstavců\".","label":"Opravit odstavec","default":"Opravit odstavec na pozici"}]}]}']);
        DB::table('h5p_libraries_languages')->insert(['library_id' => $libId, 'language_code' => 'de', 'translation' => '{"semantics":[{"label":"Medium","fields":[{"label":"Typ","description":"Medium, das wahlweise oberhalb der Aufgabe angezeigt wird."},{"label":"Bild-Zoom deaktivieren"}]},{"label":"Aufgabenbeschreibung","placeholder":"Beschreibe, was die Lernenden tun sollen ...","description":"Was die Lernenden wissen sollten."},{"label":"Absätze","entity":"Absatz","field":{"label":"Absatz"}},{"label":"Gesamtrückmeldung","fields":[{"widgets":[{"label":"Voreinstellung"}],"label":"Lege Rückmeldungen für einzelne Punktebereiche fest","description":"Klicke auf den \"Bereich hinzufügen\"-Button, um so viele Bereiche hinzuzufügen, wie du brauchst. Beispiel: 0-20% Schlechte Punktzahl, 21-91% Durchschnittliche Punktzahl, 91-100% Großartige Punktzahl!","entity":"Bereich","field":{"fields":[{"label":"Punktebereich"},{},{"label":"Rückmeldung für jeweiligen Punktebereich","placeholder":"Trage die Rückmeldung ein"}]}}]},{"label":"Verhaltenseinstellungen","description":"Diese Optionen kontrollieren, wie sich die Aufgabe verhält.","fields":[{"label":"Bewertungsmodus","description":"Wähle, ob Punkte für jeden an der exakt richtigen Stelle platzierten Absatz vergeben werden oder für jeden Absatz, der direkt nach dem Absatz platziert wird, nach dem er platziert werden soll (\"korrekte Reihenfolge\")","options":[{"label":"Korrekt platzierter Absatz"},{"label":"Richtige Reihenfolge"}]},{"label":"Punktabzug verwenden","description":"Wähle, ob für jeden Absatz, der nicht richtig positioniert ist, ein Punkt abgezogen werden soll."},{"label":"Austauschbare identische Absätze","description":"Wenn gewählt, sind beim Prüfen der Antwort Absätze mit gleichem Wortlaut untereinander austauschbar."},{"label":"Buttons zum Bewegen anzeigen","description":"Auf Mobilgeräten können die Buttons zum Verschieben von Absätzen die Barrierefreiheit verbessern. Du kannst sie hier auch deaktivieren."},{"label":"\"Wiederholen\"-Button anzeigen"},{"label":"\"Lösung zeigen\"-Button anzeigen"}]},{"label":"Bedienoberfläche","fields":[{"label":"Beschriftung des \"Überprüfen\"-Buttons","default":"Prüfen"},{"label":"Beschriftung des \"Absenden\"-Buttons","default":"Absenden"},{"label":"Beschriftung des \"Wiederholen\"-Buttons","default":"Wiederholen"},{"label":"Beschriftung des \"Lösung anzeigen\"-Buttons","default":"Lösung anzeigen"},{"label":"Beschriftung des \"Nach oben\"-Buttons","default":"Nach oben"},{"label":"Beschriftung des \"Nach unten\"-Buttons","default":"Nach unten"},{"label":"Beschriftung für einen Button, der deaktiviert ist","default":"Deaktiviert"}]},{"label":"Vorlesewerkzeug","fields":[{"label":"Vorlesewerkzeug-Beschreibung für den \"Überprüfen\"-Button","default":"Die Antworten überprüfen. Die Antwort wird als richtig oder falsch markiert."},{"label":"Vorlesewerkzeug-Beschreibung für den \"Lösung anzeigen\"-Button","default":"Zeige die Lösung. Die korrekte Lösung wird dann angezeigt."},{"label":"Vorlesewerkzeug-Beschreibung für den \"Wiederholen\"-Button","default":"Wiederhole die Aufgabe. Setzt alle Eingaben zurück und fängt von vorne an."},{"label":"Dein Ergebnis","description":"@score wird durch die erreichten Punkte ersetzt. @total wird durch die maximal mögliche Punktzahl ersetzt.","default":"Du hast @score von @total Punkten erreicht"},{"label":"Beschreibung der Liste","default":"Sortierbare Liste von Absätzen."},{"label":"Beschreibung der Liste (im \"Antwort prüfen\"-Modus)","default":"Liste der Absätze mit Ergebnissen."},{"label":"Beschreibung der Liste (im \"Lösung anzeigen\"-Modus)","default":"Liste der Absätze mit Lösungen."},{"label":"Absatz","default":"Absatz"},{"label":"Richtig","default":"richtig"},{"label":"Falsch","default":"falsch"},{"description":"@score wird durch 1 oder -1 ersetzt.","label":"Erklärung der Punktevergabe","default":"@score Punkt"},{"label":"Absatznummerierung","default":"@current von @total","description":"@current wird durch die aktuelle Absatznummer ersetzt. @total wird durch die Anzahl der Absätze ersetzt."},{"label":"Aktuelle Position in der Liste","default":"Aktuelle Position in der Liste","description":"Wird gefolgt von \"Absatznummerierung\"."},{"label":"Anweisung, wenn Absatz ausgewählt wird","default":"Drücke die Leertaste, um neu einzusortieren"},{"label":"Anweisung, wenn Absatz verschoben wird","default":"Drücke die Pfeiltasten nach oben und unten, um die Position zu ändern, die Leertaste zum Ablegen, Escape zum Abbrechen"},{"label":"Zum Verschieben ausgewählt","default":"Zum Verschieben ausgewählt"},{"label":"Verschoben","default":"Verschoben"},{"label":"Abgelegt","default":"Abgelegt"},{"label":"Sortieren abgebrochen","default":"Sortieren abgebrochen"},{"description":"Wird gefolgt von \"Absatznummerierung\".","label":"Letzte Stelle","default":"Letzte Stelle"},{"label":"Nächster Absatz","default":"Nächster Absatz","description":"Es folgt \"richtig\" oder \"falsch\"."},{"label":"Korrekter Absatz","description":"Wird gefolgt von \"Absatznummerierung\".","default":"Richtiger Absatz in Position"}]}]}']);
        DB::table('h5p_libraries_languages')->insert(['library_id' => $libId, 'language_code' => 'el', 'translation' => '{"semantics":[{"label":"Μέσα","fields":[{"label":"Τύπος","description":"Προαιρετικά μέσα που θα εμφανίζονται πάνω από την ερώτηση."},{"label":"Απενεργοποίηση ζουμ εικόνας"}]},{"label":"Περιγραφή εργασίας","placeholder":"Περιγράψτε τι πρέπει να κάνουν οι μαθητές σας ...","description":"Τι πρέπει να γνωρίζουν οι μαθητές σας."},{"label":"Παράγραφοι","entity":"παράγραφος","field":{"label":"Παράγραφος"}},{"label":"Συνολική ανατροφοδότηση","fields":[{"widgets":[{"label":"Προεπιλογή"}],"label":"Ορίστε προσαρμοσμένα σχόλια για οποιοδήποτε εύρος βαθμολογίας","description":"Κάντε κλικ στο κουμπί \"Προσθήκη εύρους\" για να προσθέσετε όσα εύρη χρειάζεστε. Παράδειγμα: 0-20% Κακή βαθμολογία, 21-91% Μέση βαθμολογία, 91-100% Μεγάλη βαθμολογία!","entity":"εύρος","field":{"fields":[{"label":"Εύρος βαθμολογίας"},{},{"label":"Ανατροφοδότηση για καθορισμένο εύρος βαθμολογίας","placeholder":"Συμπληρώστε την ανατροφοδότηση"}]}}]},{"label":"Ρυθμίσεις συμπεριφοράς","description":"Αυτές οι επιλογές θα σας επιτρέψουν να ελέγξετε πώς συμπεριφέρεται η εργασία.","fields":[{"label":"Λειτουργία βαθμολόγησης","description":"Αποφασίστε αν θα δώσετε πόντους για κάθε σωστά τοποθετημένη παράγραφο ή για κάθε παράγραφο που τοποθετείται μετά την παράγραφο που υποτίθεται ότι τοποθετείται μετά την (\"σωστή ακολουθία\")","options":[{"label":"Σωστά τοποθετημένη παράγραφος"},{"label":"Σωστή ακολουθία"}]},{"label":"Εφαρμογή ποινών","description":"Αποφασίστε αν θα αφαιρέσετε ένα σημείο για κάθε παράγραφο που δεν έχει τοποθετηθεί σωστά."},{"label":"Εναλλάξιμες διπλές παράγραφοι","description":"Εάν οριστεί, κατά τον έλεγχο της απάντησης, οι διπλές παράγραφοι θα αντιμετωπίζονται ως πανομοιότυπες εάν το απλό κείμενό τους είναι ίσο."},{"label":"Προσθήκη κουμπιών για κίνηση","description":"Σε φορητές συσκευές, τα κουμπιά για τη μετακίνηση παραγράφων μπορούν να προσφέρουν ένα επιπλέον όφελος προσβασι