        DB::table('h5p_libraries_languages')->insert(['library_id' => $libId, 'language_code' => 'fr', 'translation' => '{"semantics":[{"label":"Média","fields":[{"label":"Type","description":"Média facultatif pour afficher au-dessus de la question."},{"label":"Bloquer le zoom d’image"}]},{"label":"Description de la tâche","placeholder":"Décrivez ce que vos étudiants devraient faire...","description":"Ce que vos élèves devraient savoir."},{"label":"Paragraphes","entity":"paragraphe","field":{"label":"Paragraphe"}},{"label":"Feedback général","fields":[{"widgets":[{"label":"Par défaut"}],"label":"Définir un feedback personnalisé pour n\'importe quelle gamme de note","description":"Cliquez sur la touche « Ajouter une gamme » pour ajouter autant de gammes que nécessaire. Exemple : 0-20 % mauvaise note, 21-91 % note moyenne, 91-100 % excellente note !","entity":"gamme","field":{"fields":[{"label":"Gamme de notes"},{},{"label":"Feedback pour une gamme de notes définie","placeholder":"Compléter le feedback"}]}}]},{"label":"Paramètres comportementaux","description":"Ces options vous permettront de contrôler le déroulement de la tâche.","fields":[{"label":"Mode de notation","description":"Décider si vous attribuez des points pour chaque paragraphe correctement placé ou pour chaque paragraphe qui est placé après le paragraphe qu\'il est censé suivre (« séquence correcte »)","options":[{"label":"Paragraphe correctement placé"},{"label":"Séquence correcte"}]},{"label":"Appliquer les pénalités","description":"Décider si vous souhaitez déduire un point pour chaque paragraphe qui n\'est pas positionné correctement."},{"label":"Paragraphes en double interchangeables","description":"Si cette option est définie, lors de la vérification de la réponse, les paragraphes en double seront traités comme identiques si leur texte brut est égal."},{"label":"Ajouter des touches pour le mouvement","description":"Sur les appareils mobiles, les touches permettant de déplacer des paragraphes peuve